with with_gaps as (select *, case when started_at - lag(started_at) over (partition by country order by started_at, id) > interval '30' day then 1 else 0 end as new_group_flag from sessions), islands as (select *, sum(new_group_flag) over (partition by country order by started_at, id rows between unbounded preceding and current row) as burst_id from with_gaps) select country, count(case when device = 'mobile' then 1 end) as mobile_count, size(collect_set(device)) as num_devices, count(distinct browser) as distinct_browsers from islands group by country
